/// <summary>
/// This class is extension of Markup class and was brought in to address CB326: auto charges header shrink wrap
/// </summary>
[ExtensionOf(classStr(Markup))]
final class METMarkup_Extension
{

}

Method.Source:
    /// <summary>
    /// COC method that Returns the calculated miscellaneous charges amount for an miscellaneous charges transaction based Charges Method for Shrink wrap.
    /// </summary>
    /// <param name="_markupTrans">
    ///    The miscellaneous charges transaction to calculate miscellaneous charges amount from.
    /// </param>
    /// <param name = "_refReturnInvoiceTrans_W">
    ///     An instance of <c>RefReturnInvoiceTrans_W</c> class.
    /// </param>
    /// <param name="_qty">
    ///    The quantity to calculate miscellaneous charges amount from.
    /// </param>
    /// <param name="_value">
    ///    The value to calculate miscellaneous charges amount from.
    /// </param>
    /// <param name="_interCompanyValue">
    ///    The intercompany value to calculate miscellaneous charges amount from; optional.
    /// </param>
    /// <param name="_transDate">
    ///    The date that is used to convert miscellaneous charges from one currency to another currency;
    ///    optional.
    /// </param>
    /// <param name="_absoluteValue">
    ///     The absolute value of the related markup transaction.
    /// </param>
    /// <param name="_parmId">
    ///     The ID for the relating markup transaction.
    /// </param>
    /// <param name="_mcrPostingInvoice">
    ///     The posting invoice record of the related markup transaction.
    /// </param>
    /// <param name="_isInterCompanyMarkup">
    ///     Boolean value, states if calculation is performed for intercompany purchase order; optional.
    /// </param>
    /// <returns>
    ///    The calculated miscellaneous charges amount.
    /// </returns>
    protected static MarkupAmount getMarkupAmountFromMarkupCategory(MarkupTrans             _markupTrans,
                                                                    RefReturnInvoiceTrans_W _refReturnInvoiceTrans_W,
                                                                    Qty                     _qty,
                                                                    AmountCur               _value,
                                                                    AmountCur               _interCompanyValue,
                                                                    TransDate               _transDate,
                                                                    AmountCur               _absoluteValue,
                                                                    ParmId                  _parmId,
                                                                    boolean                 _mcrPostingInvoice,
                                                                    boolean                 _isInterCompanyMarkup)
    {
        MarkupAmount    markupAmount;
        Weight          totalWeight;
        Volume          totalVolume;

        markupAmount = next getMarkupAmountFromMarkupCategory(_markupTrans, _refReturnInvoiceTrans_W, _qty, _value,
                                                              _interCompanyValue, _transDate, _absoluteValue, _parmId,
                                                              _mcrPostingInvoice, _isInterCompanyMarkup);

        //The calculation must takes place only for Sales Order header and when the applied Auto charge is enabled for Advanced calculation
        if (_markupTrans.TransTableId == tableNum(SalesTable) && _markupTrans.METAdvancedCalculation && _markupTrans.METChargesMethod != METChargesMethod::None)
        {
            CurrencyCode parentCurrencyCode = _markupTrans.parentCurrencyCode();
            SalesTable salesTable = SalesTable::findRecId(_markupTrans.TransRecId);

            switch(_markupTrans.METChargesMethod)
            {
                //If charges method on the Markup transaction is set for Weight, then, Markup value is multiplied with total weight (With out of the Box Currency conversion procedure) avoiding Category calculation)
                case METChargesMethod::Weight:
                    [totalWeight, totalVolume] = salesTable.METGetTotalWeightAndVolume();
                    markupAmount = CurrencyExchangeHelper::amount(_markupTrans.Value * totalWeight, parentCurrencyCode);
                    break;
                //If charges method on the Markup transaction is set for Volume, then, Markup value is multiplied with total Volume (With out of the Box Currency conversion procedure) avoiding Category calculation)
                case METChargesMethod::Volume:
                    [totalWeight, totalVolume] = salesTable.METGetTotalWeightAndVolume();
                    markupAmount = CurrencyExchangeHelper::amount(_markupTrans.Value * totalVolume, parentCurrencyCode);
                    break;
                case METChargesMethod::Pallet:
                    markupAmount = CurrencyExchangeHelper::amount(_markupTrans.Value * Markup::METGetTotalContainerQty(salesTable.SalesId, METWHSContainerChargesMethod::ShrinkWrap, _markupTrans.MarkupCode), parentCurrencyCode);
                    break;
                case METChargesMethod::SecurityCap:
                    markupAmount = CurrencyExchangeHelper::amount(_markupTrans.Value * Markup::METGetTotalContainerQty(salesTable.SalesId, METWHSContainerChargesMethod::SecurityCap, _markupTrans.MarkupCode), parentCurrencyCode);
                    break;
                // CB326 Header charges for admin fees (Total cases)
                case METChargesMethod::TotalCases:
                    // get the SO Total > measurements qty
                    // Do not trigger SalesTotals::displayFieldsServer to get the qty as infinite loop and when invoice is created qty = 0 in the totals screen
                    // Instead get the qty from delivery note, we will always have 1 delivery note and 1 invoice for a sales order.
                    //container displayFields = SalesTotals::displayFieldsServer(salesTable, SalesUpdate::All, salesTable.CurrencyCode);

                    // charges calculation Charge Value * (Total Cases on Sales Order)                    
                    markupAmount = CurrencyExchangeHelper::amount(salesTable.METHeaderChargesTotalCasesAmount(_markupTrans.Value), parentCurrencyCode);
                    break;
            }

        }

        return markupAmount;
    }

    private static Qty METGetTotalContainerQty(SalesId _salesId, METWHSContainerChargesMethod _containerChargesMethod, MarkupCode _markupCode)
    {
        METSalesOrderShipmentLoadHeader salesOrderShipmentLoadHeader;
        MetContainerTable containerTable;
        WHSContainerType containerType;

        select sum(ContainerQty) from containerTable
            where containerTable.OrderNum == _salesId
            && containerTable.ContainerTypeCode == _markupCode
            exists join containerType
            where containerType.METWHSContainerChargesMethod == _containerChargesMethod
               && containerType.ContainerTypeCode == containerTable.ContainerTypeCode
            exists join salesOrderShipmentLoadHeader
            where salesOrderShipmentLoadHeader.ShipmentId == containerTable.ShipmentId;

        return containerTable.ContainerQty;
    }

    /// <summary>
    /// CB748_PricingConditions
    /// Copied from InsertMarkupTrans with a new _metRebateCodes parameter
    /// </summary>
    /// <param name = "_moduleCategory">OOTB parameter</param>
    /// <param name = "_moduleType">OOTB parameter</param>
    /// <param name = "_source">OOTB parameter</param>
    /// <param name = "_account">OOTB parameter</param>
    /// <param name = "_accountGroup">OOTB parameter</param>
    /// <param name = "_currency">OOTB parameter</param>
    /// <param name = "_languageId">OOTB parameter</param>
    /// <param name = "_item">OOTB parameter</param>
    /// <param name = "_itemGroup">OOTB parameter</param>
    /// <param name = "_invertSign">OOTB parameter</param>
    /// <param name = "_deleteExistingMarkupTrans">OOTB parameter</param>
    /// <param name = "_dlvModeId">OOTB parameter</param>
    /// <param name = "_dlvModeGroup">OOTB parameter</param>
    /// <param name = "_totalAmount">OOTB parameter</param>
    /// <param name = "_mcrReturnMarkup">OOTB parameter</param>
    /// <param name = "_metRebateCodes">New parameter to retrieve and add the auto charge lines for rebate codes</param>
    public static void METInsertMarkupTrans(
        HeadingLine         _moduleCategory,
        MarkupModule        _moduleType,
        Common              _source,
        CustVendAC          _account,
        MarkupGroupId       _accountGroup,
        CurrencyCode        _currency,
        LanguageId          _languageId = CompanyInfo::languageId(),
        ItemId              _item = '',
        MarkupGroupId       _itemGroup = '',
        boolean             _invertSign = false,
        boolean             _deleteExistingMarkupTrans = true,
        DlvModeId           _dlvModeId   = '',
        MarkupGroupId       _dlvModeGroup = '',
        Amount              _totalAmount = 0,
        NoYesId             _mcrReturnMarkup  = false,
        boolean             _metRebateCodes = true) // Adding new parameter
    {
        MarkupTransInsertParameters parameters = MarkupTransInsertParameters::construct();
        InventDim locInventDimParameters       = Markup::parmInventDimParameters();
        
        Markup::metClearRebateAutoCharges(_source);

        parameters.ModuleCategory = _moduleCategory;
        parameters.ModuleType = _moduleType;
        parameters.Source = _source;
        parameters.Account = _account;
        parameters.AccountGroup = _accountGroup;
        parameters.Currency = _currency;
        parameters.LanguageId = _languageId;
        parameters.Item = _item;
        parameters.InventSiteId = locInventDimParameters.InventSiteId;
        parameters.InventLocationId = locInventDimParameters.InventLocationId;
        parameters.ItemGroup = _itemGroup;
        parameters.InvertSign = _invertSign;
        parameters.DeleteExistingMarkupTrans = _deleteExistingMarkupTrans;
        parameters.DlvModeId = _dlvModeId;
        parameters.DlvModeGroup = _dlvModeGroup;
        parameters.TotalAmount = _totalAmount;
        parameters.McrReturnMarkup = _mcrReturnMarkup;

        parameters.METRebateCodes = _metRebateCodes;

        MarkupTransInsert markupTransInsert = MarkupTransInsert::construct();
        markupTransInsert.insert(parameters);
    }

    /// <summary>
    /// Clear all the offremittance auto-charges added previously
    /// </summary>
    /// <param name = "_source">Source record</param>
    public static void metClearRebateAutoCharges(Common _source)
    {
        MarkupTrans markupTrans;
        MarkupTable markupTable;

        ttsbegin;

        while select forupdate markupTrans
            index hint TableRecIdIdx
            where markupTrans.TransTableId == _source.TableId
                  && markupTrans.TransRecId == _source.RecId
            exists join markupTable
            where markupTable.MarkupCode == markupTrans.MarkupCode
            && markupTable.METIsOffRemittance == NoYes::Yes
        {
            if (markupTrans.validateDelete())
            {
                markupTrans.delete();
            }
        }

        ttscommit;
    }

    /// <summary>
    /// Overrides the initJournalMarkupTrans method to adjust markup calculation
    /// for return orders. When the related SalesTable record indicates a return
    /// (ReturnItemNum is populated), this method retrieves the original Sales
    /// Order's MarkupTrans record (including line number) and applies its
    /// CalculatedAmount to the current journal markup.
    /// </summary>
    /// <param name="_markupTrans">
    ///     The source MarkupTrans record being initialized.
    /// </param>
    /// <param name="_destin">
    ///     The destination record (Common) for the markup transaction.
    /// </param>
    /// <param name="_calculatedAmount">
    ///     The calculated amount for the markup transaction.
    /// </param>
    /// <param name="_voucher">
    ///     The voucher number associated with the transaction.
    /// </param>
    /// <param name="_transDate">
    ///     The transaction date.
    /// </param>
    /// <param name="_posted">
    ///     The posted amount for the markup transaction.
    /// </param>
    /// <param name="_originalMarkupTrans">
    ///     The original markup transaction record, if available.
    /// </param>
    /// <returns>
    ///     A MarkupTrans record with updated CalculatedAmount when the
    ///     SalesTable indicates a return order; otherwise, the base
    ///     MarkupTrans record returned by the super call.
    /// </returns>
    protected MarkupTrans initJournalMarkupTrans(MarkupTrans _markupTrans,
                                             Common _destin,
                                             AmountCur _calculatedAmount,
                                             Voucher _voucher,
                                             TransDate _transDate,
                                             AmountCur _posted,
                                             MarkupTrans _originalMarkupTrans)
    {
        MarkupTrans locMarkup;

        locMarkup = next initJournalMarkupTrans(_markupTrans,
                                            _destin,
                                            _calculatedAmount,
                                            _voucher,
                                            _transDate,
                                            _posted,
                                            _originalMarkupTrans);

        CustInvoiceJour custInvoiceJour;
        SalesTable      salesTable;
        MarkupTrans     markupSo;

        select firstOnly RecId from custInvoiceJour
        join RecId from salesTable
            where salesTable.SalesId == custInvoiceJour.SalesId
              && salesTable.ReturnItemNum != ''   // only return orders
              && custInvoiceJour.RecId == locMarkup.TransRecId
              && custInvoiceJour.TableId == locMarkup.TransTableId
        join CalculatedAmount, RecId from markupSo
            where markupSo.TransTableId == tableNum(SalesTable)
              && markupSo.TransRecId   == salesTable.RecId
            && markupSo.LineNum == locMarkup.LineNum;
        
        if (markupSo.RecId)
        {
            locMarkup.CalculatedAmount = markupSo.CalculatedAmount;
        }
        

        return locMarkup;
    }
